      restore(frame);
      while (frame.next < frame.candidates.length) {
        const version = frame.candidates[frame.next++];
        selected.set(frame.name, version);
        if (append(version.deps)) return true;
        restore(frame);
      }
      choices.pop();
    }
    return false;
