'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare } = require('./src/semver');

// Caret zero-major rules.
assert.equal(satisfies('0.2.9', '^0.2.0'), true);
assert.equal(satisfies('0.3.0', '^0.2.0'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('1.9.0', '~1.2.0'), false);
assert.equal(compare('1.10.0', '1.9.0'), 1);

// Backtracking must undo constraints from abandoned choices.
const reg = {
  a: { '2.0.0': { b: '^2.0.0' }, '1.0.0': { b: '^1.0.0' } },
  b: { '2.0.0': { c: '9.9.9' }, '1.0.0': {} },
  c: { '1.0.0': {} },
};
assert.deepEqual(resolve(reg, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
// Stale constraint from a.2 (b ^2) must not block b@1 after backtracking.
const reg2 = {
  a: { '2.0.0': { b: '^2.0.0', x: '1.0.0' }, '1.0.0': {} },
  b: { '2.0.0': {}, '1.0.0': {} },
  x: {},
};
assert.deepEqual(resolve(reg2, { a: '*', b: '*' }), { a: '1.0.0', b: '2.0.0' });

// Cycles terminate.
const cyc = { a: { '1.0.0': { b: '*' } }, b: { '1.0.0': { a: '*' } } };
assert.deepEqual(resolve(cyc, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
const cycBad = { a: { '1.0.0': { b: '*' } }, b: { '1.0.0': { a: '2.0.0' } } };
assert.equal(resolve(cycBad, { a: '*' }), null);

// Long chain, beyond any small iteration cap or recursion depth.
const chain = {};
const N = 50000;
for (let i = 0; i < N; i += 1) chain['p' + i] = { '1.0.0': i + 1 < N ? { ['p' + (i + 1)]: '^1.0.0' } : {} };
assert.equal(Object.keys(resolve(chain, { p0: '*' })).length, N);

// Deep backtracking: many choice points before a conflict found late.
const wide = { root: { '1.0.0': {} } };
const deps = {};
for (let i = 0; i < 12; i += 1) {
  wide['q' + i] = { '3.0.0': {}, '2.0.0': {}, '1.0.0': {} };
  deps['q' + i] = '*';
}
wide.z = { '1.0.0': { q0: '1.0.0' } };
deps.z = '*';
assert.deepEqual(resolve(wide, deps).q0, '1.0.0');

// Missing package -> null; unreachable malformed entry throws.
assert.equal(resolve({}, { nope: '*' }), null);
assert.throws(() => resolve({ a: { '1.0.0': {} }, junk: { '01.0.0': {} } }, { a: '*' }), TypeError);
assert.throws(() => resolve({ junk: { '1.0.0': { a: '^x' } } }, {}), TypeError);
assert.deepEqual(resolve({}, {}), {});

// __proto__ names.
const proto = JSON.parse('{"__proto__": {"1.0.0": {}}}');
const out = resolve(proto, JSON.parse('{"__proto__": "*"}'));
assert.equal(Object.getOwnPropertyDescriptor(out, '__proto__').value, '1.0.0');
console.log('smoke ok');

